  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C48"],
      "claim": "Rosaramicin, a complex macrocyclic lactone antibiotic, has absolute oral bioavailability of 32–39% in humans after 500 mg oral doses, supporting high F for the query's lactone-rich polycyclic scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Retrorsine, a macrocyclic diester natural product, has a predicted absolute oral bioavailability of 44%, supporting high F for a polycyclic ester/lactone query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C47"],
      "claim": "Idarubicin, a complex polycyclic natural product, shows oral bioavailability of about 39% in humans, supporting F ≥ 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Artemisinin, the closest Morgan match, is reported to have low oral bioavailability in humans, but this is confounded by its endoperoxide and poor solubility and is only weakly transferable to the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C20"],
      "claim": "5-Hydroxyrofecoxib has a low oral bioavailability of 0.140 in healthy subjects, but its aromatic sulfone-lactone structure is distant from the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "low",
  "decision_summary": "Predicted high (F ≥ 20%) based on a preponderance of transferable absolute oral bioavailability values in complex lactone/macrocyclic natural products (rosaramicin 32–39%, retrorsine 44%, idarubicin ~39%), while the closest Morgan match artemisinin is confounded by its endoperoxide and mixed reports; explicit low-F analogues are structurally distant.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability data for the query or a close structural analogue; all Morgan similarities are below 0.18.",
    "Artemisinin evidence is conflicting and its endoperoxide/solubility liabilities may not apply to the query's lactone-rich, hydroxylated scaffold.",
    "The exact structural class of the query (e.g., triptolide-like diterpenoid) is not directly represented among the evidence molecules."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

